  \node[below right] at (3,0) {$C$};
  \draw[ink] (1.15,2.05) -- (0,0) -- (3,0) -- (1.15,2.05);
  \fill[ink] (1.5,0.5061) circle (1.3pt);
  \node[below right] at (1.5,0.5061) {$O$};
  \node[below, font=\small] at (1.5,-1.25) {a)};
  \draw[ink] (5.8946,0.7581) circle (0.7581);
  \node[above] at (5.75,2.05) {$M$};
  \node[below left] at (4.6,0) {$N$};
  \node[below right] at (7.6,0) {$P$};
  \draw[ink] (5.75,2.05) -- (4.6,0) -- (7.6,0) -- (5.75,2.05);
  \fill[ink] (5.8946,0.7581) circle (1.3pt);
  \node[below] at (5.8946,0.7581) {$I$};
  \node[below, font=\small] at (6.1,-1.25) {b)};
\end{tikzpicture}
}\par\vspace{2pt}{\sffamily\scriptsize\itshape\color{muted}Hình 2}\end{center}\smallskip {\sffamily\bfseries\color{brand}Lời giải}[[br]]Hình a): $(O)$ ngoại tiếp tam giác $ABC$ nên $O$ cách đều ba đỉnh $A$, $B$, $C$.[[br]]Điểm cách đều hai đầu mút một đoạn thẳng thì nằm trên đường trung trực của đoạn đó, nên $O$ là giao điểm của ba đường trung trực.[[br]]Hình b): $(I)$ nội tiếp tam giác $MNP$ nên $I$ cách đều ba cạnh.[[br]]Điểm cách đều hai cạnh của một góc thì nằm trên tia phân giác của góc đó, nên $I$ là giao điểm của ba đường phân giác.[[br]]Vậy $O$ là giao ba đường trung trực, $I$ là giao ba đường phân giác.

\begin{minipage}[t]{0.58\linewidth}\vspace{0pt}\textbf{Ví dụ 3.} Cho tam giác $ABC$ vuông tại $A$ có $AB = 6$ cm, $AC = 8$ cm (Hình 3). Xác định tâm và tính bán kính đường tròn ngoại tiếp tam giác $ABC$. [[br]]{\sffamily\bfseries\color{brand}Lời giải}[[br]]Xét tam giác $ABC$ vuông tại $A$, theo định lí Pythagore:[[br]]$BC^2 = AB^2 + AC^2 = 6^2 + 8^2 = 36 + 64 = 100$.[[br]]Suy ra $BC = \sqrt{100} = 10$ (cm).[[br]]Vì tam giác $ABC$ vuông tại $A$ nên tâm đường tròn ngoại tiếp là trung điểm $O$ của cạnh huyền $BC$.[[br]]Bán kính $R = \dfrac{BC}{2} = \dfrac{10}{2} = 5$ (cm).[[br]]Vậy tâm là trung điểm $BC$ và $R = 5$ cm.\end{minipage}\hfill\begin{minipage}[t]{0.36\linewidth}\vspace{0pt}
\centering
\adjustbox{max width=\linewidth, max totalheight=3.4cm}{
\begin{tikzpicture}[line width=0.8pt, font=\small]
  \draw[ink] (1.65,1.2375) circle (2.0625);
  \node[below left] at (0,0) {$A$};
  \node[above left] at (0,2.475) {$B$};
  \node[below right] at (3.3,0) {$C$};
  \draw[ink] (0,0) -- (0,2.475) -- (3.3,0) -- (0,0);
  \fill[ink] (1.65,1.2375) circle (1.3pt);
